Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=('a20ee54cad53c10bdae40265c72896816a43af4716da96f8ffa0b915d54f65f9',), event=Revised(decision='gatehalves', at=datetime(2026, 11, 20, 0, 0, 0), actor='assistant', title="The merge gate has two halves: --no-live, a function of the tree, and --only-live, which reads the owner's data", body="It has TWO HALVES (2026-10-03): `--no-live` is the tree half, a function of the tree alone, run with the data tree hidden (`SUZATARY_INSTANCE` names nothing), so it runs on core's runners from the train commit's public tree (`train`); `--only-live` is the live half, on the box only: the steps that read the owner's data tree (`--test live`, the `all` modules in `live_modules`, the guards that read beyond the public tree, `web-live`) and the deploy's checks. `--list` names every step's half, and `app/cli/tests/guards/merge_gate.rs` fails when a test that reads the data tree is outside the live half.", rationale="Decided 2026-10-03. Restated 2026-11-20: the tree half runs on core's runners, and the Codespace it ran in is gone.", supersedes=()))